// Async server component that fetches and displays the current user
interface User {
  name: string
  email: string
}

async function getUser(): Promise<User | null> {
  try {
    const res = await fetch('/api/users/profile')
    return res.json()
  } catch {
    // Return mock data for build time
    return { name: 'Sample User', email: 'user@example.com' }
  }
}

export default async function UserProfile() {
  const user = await getUser()

  if (!user) {
    return <div>User profile not available</div>
  }

  return (
    <div>
      <h2>User Profile</h2>
      <div>{user.name}</div>
      <div>{user.email}</div>
    </div>
  )
}
